%[text] %[text:anchor:T_1FFD3858] # Longitudinal Vehicle - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Braking
model_name = "HarnessModel_Vehicle1D";
load_system(model_name)

Vehicle1D_Basic_params

set_param(model_name + "/Longitudinal Vehicle", ReferencedSubsystem = "Vehicle1D_Basic_refsub");

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_Vehicle1D_Braking_refsub");
%[text] 
initial.vehicle_speed_kph = 0;

sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "400");

sim_out = sim(sim_in);

sim_data = extractTimetable(sim_out.logsout);

signal_names = [
  "Axle torque input"
  "Brake force"
  "Road inclination"
  "Road grade"
  "G force"
  "Vehicle speed kph"
  "Vehicle speed mph"
  "Axle speed"
  ];

for idx = 1 : numel(signal_names) %[output:group:5658d334]
  fig = SignalTool2.plotTimedData(TimedData = sim_data, SignalName = signal_names(idx)); %[output:751ae745] %[output:72b6f24a] %[output:63a0641a] %[output:27e71b7b] %[output:977b6d53] %[output:7f03c498] %[output:5cd14011] %[output:9ce92a64]
  fig.Position(4) = 200;  % height
end  % for %[output:group:5658d334]
